alue="<?=$user['id']?>" <?=(int)($item['assigned_to_user_id']??0)===(int)$user['id']?'selected':''?>><?=e($user['name'])?></option><?php endforeach;?></select><input type="date" name="due_date" value="<?=e($item['due_date']??'')?>"><button class="btn btn-small btn-secondary" type="submit">Update</button></form><form method="post" class="no-print" onsubmit="return confirm('Delete this action item?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_action"><input type="hidden" name="action_id" value="<?=$item['id']?>"><input type="hidden" name="provider_id" value="<?=$provider['id']?>"><input type="hidden" name="month" value="<?=e($monthKey)?>"><button class="btn btn-small btn-danger" type="submit">Delete</button></form><?php endif;?></article><?php endforeach;?></div><?php else:?><div class="empty-inline">No action items have been added for this review.</div><?php endif;?>
